        private void copyAssetsTessDataToSD(String lang) {
            String[] paths = {MainActivity.DATA_PATH_LANGUAGE, MainActivity.DATA_PATH_LANGUAGE + "tessdata/"};
            for (String path : paths) {
                File dir = new File(path);
                if (!dir.exists()) {
                    if (!dir.mkdirs()) {
                        Log.v(MainActivity.TAG, "ERROR: Creation of directory " + path + " on sdcard failed");
                        return;
                    }
                    Log.v(MainActivity.TAG, "Created directory " + path + " on sdcard");
                }
            }
            if (!new File(MainActivity.DATA_PATH_LANGUAGE + "tessdata/" + lang + ".traineddata").exists()) {
                try {
                    AssetManager assetManager = MainActivity.this.getBaseContext().getAssets();
                    InputStream in = assetManager.open("tessdata/" + lang + ".traineddata");
                    OutputStream out = new FileOutputStream(MainActivity.DATA_PATH_LANGUAGE + "tessdata/" + lang + ".traineddata");
                    byte[] buf = new byte[1024];
                    while (true) {
                        int len = in.read(buf);
                        if (len > 0) {
                            out.write(buf, 0, len);
                        } else {
                            in.close();
                            out.close();
                            Log.v(MainActivity.TAG, "Copied " + lang + " traineddata");
                            return;
                        }
                    }
                } catch (IOException e) {
                    Log.e(MainActivity.TAG, "Was unable to copy " + lang + " traineddata " + e.toString());
                }
            }
        }

